'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const STORE='turi.gestion.demo.v1';
function readStore(){try{const d=JSON.parse(localStorage.getItem(STORE));return validState(d)?d:clone(window.TURI_SEED)}catch{return clone(window.TURI_SEED)}}
function validState(d){return !!d&&d.version===1&&d.producer?.id==='PAS-DANI'&&['policies','alerts','claims','clients','companies','leads','drafts','tasks','documents','chat','activity'].every(k=>Array.isArray(d[k]))&&d.policies.length===230&&d.companies.length===15&&!!d.preferences&&Array.isArray(d.preferences.courses)&&d.policies.every(p=>p&&['id','client','risk','category','company','expiry','status'].every(k=>typeof p[k]==='string'))&&d.alerts.every(a=>a&&typeof a.id==='string'&&typeof a.title==='string'&&['red','yellow','green'].includes(a.priority))&&d.claims.every(c=>c&&typeof c.id==='string'&&Array.isArray(c.notes))&&d.documents.every(d=>d&&typeof d.name==='string'&&typeof d.text==='string')&&d.chat.every(m=>m&&typeof m.text==='string'&&['user','assistant'].includes(m.role))&&d.leads.every(l=>l&&typeof l.name==='string')&&d.tasks.every(t=>t&&typeof t.title==='string')&&d.drafts.every(t=>t&&typeof t.id==='string'&&t.coverageIssued===false)&&d.activity.every(a=>a&&typeof a.action==='string');}
let S=readStore(), activeFilter='Todas', policySearch='', policyCompany='', policyCategory='', policyPage=1, adminTab='resumen', marketingTab='oportunidades', quoteStep=1, Q={category:'Autos',brand:'',model:'',year:'',postal:'',usage:'Particular',name:'',email:'',phone:'',dob:'',identity:'',payment:'Débito a configurar con la compañía',marketing:false}, selectedOffer=null;
let role=sessionStorage.getItem('turi.demo.role')||null;
const svgPaths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5',shield:'M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11zM9 12l2 2 4-4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',search:'M21 21l-5.2-5.2M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',arrow:'M5 12h14M13 6l6 6-6 6',chevron:'M9 5l7 7-7 7',check:'M20 6L9 17l-5-5',close:'M18 6L6 18M6 6l12 12',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',alert:'M12 3L2 21h20L12 3zM12 9v5M12 17v.1',calendar:'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',chat:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5',spark:'M12 3l2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3M20 2v4M18 4h4',briefcase:'M9 4V2h6v2M3 6h18v15H3zM3 11h18M10 11v3h4v-3',wallet:'M20 8V5H4a2 2 0 0 1 0-4h14v4M2 3v16a2 2 0 0 0 2 2h16V8H4M15 12h7v5h-7z',chart:'M3 3v18h18M8 17v-5M13 17V7M18 17v-8',link:'M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-1.8 1.8M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l1.8-1.8',external:'M14 3h7v7M21 3L10 14M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6',book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2',download:'M21 15v5H3v-5M7 10l5 5 5-5M12 15V3',upload:'M21 15v5H3v-5M7 8l5-5 5 5M12 3v12',copy:'M9 9h12v12H9zM5 15H3V3h12v2',logout:'M9 21H3V3h6M16 17l5-5-5-5M21 12H9',menu:'M3 6h18M3 12h18M3 18h18',car:'M3 17V9h18v8M5 9l2-5h10l2 5M3 13h18M5 17v3M19 17v3M6 13v1M18 13v1',home:'M3 10l9-8 9 8M5 8v14h14V8M9 22v-8h6v8',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 11v6M12 7v.1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 2h6l1 4 4 1 2 5-3 3v4l-5 3-3-3H7l-5-5 3-3V7l4-1z',mail:'M3 4h18v16H3zM3 5l9 8 9-8',attachment:'M21 11l-9 9a6 6 0 0 1-8.5-8.5l10-10a4 4 0 0 1 5.7 5.7L9 17a2 2 0 0 1-2.8-2.8l9-9'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${svgPaths[n]||svgPaths.file}"/></svg>`}
function asset(p){return window.TURI_ASSETS?.[p]||p}
function img(p,alt,cls=''){return `<img src="${esc(asset(p))}" alt="${esc(alt)}" class="${cls}" loading="lazy">`}
function logo(){return `<div class="brand">${img('assets/logo.png','Turi','brand-logo')}<span class="brand-divider"></span><span class="brand-name">GESTIÓN</span></div>`}
function company(id){return S.companies.find(c=>c.id===id)||{id,name:'A confirmar',logo:'',portal:'#'}}
function money(n){return new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n)}
function dateText(d){return new Date(d+'T12:00:00').toLocaleDateString('es-AR',{day:'2-digit',month:'short'})}
function daysSince(d){return Math.max(0,Math.round((new Date(S.demoDate+'T12:00:00')-new Date(d+'T12:00:00'))/86400000))}
function plusDays(d,n){const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)}
function save(){try{localStorage.setItem(STORE,JSON.stringify(S))}catch{toast('No se pudo guardar en este navegador. Exportá tu demo para conservar cambios.')}}
function audit(action,record){S.activity.unshift({action,record,at:new Date().toISOString(),actor:'Daniel Stern · demo'});save()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(title,body,actions=''){const el=$('#modal');$('#modal-content').innerHTML=`<div class="modal-top"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!el.open)el.showModal();}
function closeModal(){$('#modal').close()}
function navigate(route){if(location.hash==='#'+route)render();else location.hash=route;$('.shell')?.classList.remove('menu-open')}
function route(){return location.hash.replace(/^#\/?/,'')||'inicio'}
function button(label,action,cls='light',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`}
function badge(text,tone=''){return `<span class="badge ${tone}">${esc(text)}</span>`}
function demoNote(t='Demo interactiva · datos ficticios · sin conexión a aseguradoras.'){return `<div class="demo-note">${icon('info')}<span>${t}</span></div>`}
function stat(title,value,note,ico,tone=''){return `<div class="stat"><div class="stat-top">${title}<span class="stat-icon ${tone}">${icon(ico)}</span></div><strong>${value}</strong><p>${note}</p></div>`}
function pageHeader(title,desc,cta=''){return `<div class="page-header"><div><h1>${title}</h1><p>${desc}</p></div>${cta}</div>`}
const nav=[['Tu operación',[['tablero','grid','Mi día'],['polizas','file','Mis pólizas'],['siniestros','shield','Siniestros'],['cotizaciones','chart','Cotizaciones'],['clientes','users','Mis clientes']]],['Tu negocio',[['administracion','wallet','Administración'],['marketing','briefcase','Marketing y ventas']]],['Tu espacio',[['agente','spark','Agente Turi'],['capacitacion','book','Capacitación'],['accesos','link','Mis accesos']]]];
function shell(content,r){return `<div class="shell"><aside class="sidebar">${logo()}<nav aria-label="Navegación principal">${nav.map(([g,ns])=>`<div class="nav-label">${g}</div>${ns.map(([id,ic,n])=>`<button class="nav-link ${r===id?'active':''}" data-route="${id}" ${r===id?'aria-current="page"':''}>${icon(ic)}${n}${id==='siniestros'?'<span class="nav-count">5</span>':id==='agente'?'<span class="nav-count">DEMO</span>':''}</button>`).join('')}`).join('')}</nav><div class="sidebar-bottom"><button class="nav-link" data-route="ajustes">${icon('settings')}Mi perfil y respaldo</button><div class="profile-mini">${img('assets/daniel.webp','Daniel Stern','avatar')}<div><b>Daniel Stern</b><p>Turi · Productor asesor</p></div><button class="icon-btn" style="margin-left:auto;border:0;background:transparent" data-action="logout" aria-label="Cerrar sesión de demo">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><form class="global-search" id="global-search">${icon('search')}<input aria-label="Buscar cliente, póliza o patente" name="q" placeholder="Buscá un cliente, póliza o patente…" autocomplete="off"><kbd>↵</kbd></form><div class="topbar-tools">${badge('Entorno de demo')}<button class="icon-btn" data-route="tablero" aria-label="Ver alertas">${icon('bell')}<span class="notification-dot"></span></button><span class="small">Daniel Stern</span>${img('assets/daniel.webp','Perfil de Daniel Stern','avatar')}</div></header><main id="main" tabindex="-1">${content}<footer class="section-footer"><span>TURI Gestión · Pensado para el productor.</span><button class="text-btn" data-action="demo-info">Acerca de esta demo</button></footer></main></div></div>`}
function entry(){return `<div class="entry"><header>${logo()}${badge('Una plataforma pensada para vos','blue')}</header><main id="main" class="entry-main"><div class="entry-copy"><div class="eyebrow">Menos gestiones. Más tiempo para tu gente.</div><h1>Todo tu trabajo,<br><span>más simple.</span></h1><p>Tus clientes, tus compañías y lo que necesita atención. En un solo lugar, con la experiencia de Turi.</p><div class="entry-roles"><button class="role-card primary" data-action="login" data-role="productor">${icon('briefcase')}<b>Soy productor ${icon('arrow')}</b><span>Mi cartera, mi día, mi negocio.</span></button><button class="role-card" data-action="login" data-role="cliente">${icon('user')}<b>Soy cliente ${icon('arrow')}</b><span>Mis seguros y mi asesor.</span></button></div><div class="entry-points"><span>${icon('check')} Tu código. Tu cartera.</span><span>${icon('check')} Tecnología + criterio experto.</span></div><p class="no-claims">Demo navegable · usuario <b>Dani</b> · contraseña <b>1234</b></p></div><div class="entry-art"><div class="entry-card"><div class="row between"><div class="row">${img('assets/daniel.webp','Daniel Stern','avatar lg')}<div><b>Daniel Stern</b><p class="small muted">Organización · Turi</p></div></div>${badge('230 pólizas','green')}</div><div class="mock-title">Tu día, bajo control.</div><div class="mock-task"><span class="task-icon red">${icon('calendar')}</span><div><b class="small">Una renovación para hoy</b><p class="small muted">María López · La Segunda</p></div></div><div class="mock-task"><span class="task-icon">${icon('shield')}</span><div><b class="small">Un siniestro necesita seguimiento</b><p class="small muted">17 días sin novedades</p></div></div><div class="row between mt24"><span class="small muted">Todo tiene un próximo paso.</span>${icon('arrow')}</div></div><div class="entry-mini">Hacelo simple.<br><b>Hacelo Turi.</b></div></div></main><footer><span>© 2026 Turi · Colaborar & potenciar.</span><span>Prototipo de operación para productores · CatchDog</span><button class="text-btn" data-action="demo-info">Información de la demo</button></footer></div>`}
function companyTiles(companies=S.companies){return `<div class="company-grid">${companies.map(c=>`<a class="company-tile" href="${esc(c.portal)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ${esc(c.name)} · ${esc(c.portalKind)}">${c.logo?img(c.logo,c.name):`<b>${esc(c.name)}</b>`}<span>${esc(c.name)} ${icon('external')}</span></a>`).join('')}</div>`}
function alertRows(alerts){return alerts.length?alerts.map(a=>`<div class="alert-row"><span class="alert-signal ${a.priority}">${icon(a.category==='Siniestros'?'shield':a.category==='Renovaciones'?'calendar':a.priority==='green'?'check':'alert')}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.client)} · ${esc(company(a.company).name)}</p><div class="alert-meta">${badge(a.category,a.priority)}<span class="small muted" style="font-size:9px">${esc(a.source)}</span></div></div><div class="alert-due"><strong style="color:${a.priority==='red'?'var(--red)':'inherit'}">${a.due===S.demoDate?'Hoy':dateText(a.due)}</strong><button class="btn light small" data-action="alert-detail" data-id="${esc(a.id)}">Resolver ${icon('chevron')}</button></div></div>`).join(''):`<div class="empty">${icon('check')}No hay alertas pendientes en esta vista.</div>`}
function dashboard(){const alerts=S.alerts.filter(a=>!a.done);const filters=['Todas','Renovaciones','Pagos','Siniestros','Más'];const shown=alerts.filter(a=>activeFilter==='Todas'||(activeFilter==='Más'?['Bajas','Recotizaciones','Actualizaciones'].includes(a.category):a.category===activeFilter));return `<div class="page-header"><div><div class="date-label">Lunes, 19 de octubre de 2026 · Jornada de muestra</div><h1>Buen día, Dani.</h1><p>Lo importante de tu cartera, en un vistazo.</p></div>${button(icon('link')+' Mi link de cotización','share-link','blue')}</div><div class="banner"><div class="row">${icon('spark')}<div><strong>Empezá por lo que necesita tu atención.</strong><p>${alerts.filter(a=>a.priority==='red').length} prioridades para hoy. Turi te ayuda a preparar el próximo paso.</p></div></div>${button('Prepará mi día '+icon('arrow'),'agent-day','light small')}</div><div class="stats">${stat('Pólizas activas',S.policies.filter(p=>p.status==='Activa').length,'Tu cartera, siempre a mano','file','blue')}${stat('Alertas pendientes',alerts.length,'Prioridades y fechas visibles','bell','peach')}${stat('Próximas renovaciones',S.policies.filter(p=>p.expiry<=plusDays(S.demoDate,7)).length,'En los próximos 7 días','calendar')}${stat('Siniestros en seguimiento',S.claims.length,'Cada caso, con su próximo paso','shield','blue')}</div><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Tu bandeja de prioridades</h2>${button(icon('settings'),'alert-filters','light small','aria-label="Configurar alertas"')}</div><div class="filters">${filters.map(f=>`<button class="pill ${activeFilter===f?'active':''}" data-filter="${f}">${f}${f==='Todas'?` <span class="tiny-count">${alerts.length}</span>`:''}</button>`).join('')}</div><div id="alerts-list">${alertRows(shown)}</div><div class="priority-legend"><span><i class="dot" style="color:var(--red)"></i>Requiere acción hoy</span><span><i class="dot" style="color:var(--yellow)"></i>Próximo a vencer</span><span><i class="dot" style="color:var(--green)"></i>Informativo</span></div></section><section class="panel"><div class="panel-head"><h2>Mis accesos a compañías</h2><button class="text-btn" data-route="accesos">Gestionar accesos ${icon('arrow')}</button></div>${companyTiles()}<div class="company-caption"><span>15 compañías de muestra · accesos oficiales externos</span><span>Siempre con tu código PAS</span></div></section></div><aside class="dashboard-aside"><section class="agent-card">${img('assets/agente-turi.webp','Turi, tu asistente ilustrado','agent-avatar')}<h2>Conocé a Turi.</h2><p class="intro">Tu compañero para ordenar el día.</p><div class="agent-tip">“Lucía lleva <b>17 días sin novedades</b> en su siniestro. Puedo ayudarte a preparar el seguimiento.”</div>${button(icon('spark')+' Hablemos','open-agent','light')}<p class="small muted" style="text-align:center;font-size:9px;margin-top:11px">Asistente de muestra · con contexto de tu demo</p></section><section class="panel mt16"><div class="panel-head"><h2>Tu agenda</h2>${icon('calendar')}</div><div class="agenda-line"><span class="agenda-time">09:30</span><div><b>Confirmar renovación</b><p>María López · Auto</p></div></div><div class="agenda-line"><span class="agenda-time">11:00</span><div><b>Consultar peritación</b><p>Lucía García · Siniestro</p></div></div><div class="agenda-line"><span class="agenda-time">15:00</span><div><b>Control de comisiones</b><p>Liquidaciones de octubre</p></div></div></section><div class="panel mt16" style="background:#e5ebe3"><b class="small">Tu próxima oportunidad empieza con un link.</b><p class="small muted" style="margin:9px 0 14px;font-size:11px">Tu cliente carga una vez. Vos recibís la consulta ordenada.</p><button class="text-btn" data-route="cotizaciones">Preparar cotización ${icon('arrow')}</button></div></aside></div>`}
function policyList(){const rows=S.policies.filter(p=>(!policySearch||`${p.client} ${p.id} ${p.risk} ${p.category}`.toLowerCase().includes(policySearch.toLowerCase()))&&(!policyCompany||p.company===policyCompany)&&(!policyCategory||p.category===policyCategory));const totalPages=Math.max(1,Math.ceil(rows.length/15));policyPage=Math.min(policyPage,totalPages);return `${pageHeader('Mis pólizas','Toda tu cartera, con clientes, vencimientos y documentos.',button(icon('download')+' Exportar cartera','export-policies','light'))}<section class="panel"><div class="row between wrap"><span class="small"><b>230 pólizas activas</b> · cartera ficticia</span>${badge('Última carga · jornada de muestra')}</div><div class="toolbar"><input class="search-input" id="policy-search" type="search" placeholder="Nombre, patente o número de póliza" aria-label="Buscar pólizas" value="${esc(policySearch)}"><select id="policy-company" aria-label="Filtrar por compañía"><option value="">Todas las compañías</option>${S.companies.map(c=>`<option value="${c.id}" ${policyCompany===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="policy-category" aria-label="Filtrar por tipo de seguro"><option value="">Todos los seguros</option>${[...new Set(S.policies.map(p=>p.category))].map(c=>`<option ${policyCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select>${button('Limpiar','clear-policy-filters','light small')}</div><div class="table-wrap"><table><thead><tr><th>Cliente / póliza</th><th>Bien asegurado</th><th>Seguro</th><th>Compañía</th><th>Vencimiento</th><th>Estado</th><th></th></tr></thead><tbody>${rows.slice((policyPage-1)*15,policyPage*15).map(p=>`<tr><td><button class="record-name" data-action="policy-detail" data-id="${p.id}"><strong>${esc(p.client)}</strong><small>${p.id}</small></button></td><td>${esc(p.risk)}</td><td>${esc(p.category)}</td><td>${esc(company(p.company).name)}</td><td>${dateText(p.expiry)}</td><td>${badge(p.payment==='Pendiente'?'Pago pendiente':p.expiry<=plusDays(S.demoDate,7)?'Por renovar':'Activa',p.payment==='Pendiente'?'red':p.expiry<=plusDays(S.demoDate,7)?'yellow':'green')}</td><td><button class="icon-btn" data-action="policy-detail" data-id="${p.id}" aria-label="Ver póliza de ${esc(p.client)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No encontramos pólizas con esos filtros.</div>':''}</div><div class="pager"><span>${rows.length} resultados · página ${policyPage} de ${totalPages}</span><div class="row gap8"><button class="btn light small" data-action="policy-prev" ${policyPage<=1?'disabled':''}>Anterior</button><button class="btn light small" data-action="policy-next" ${policyPage>=totalPages?'disabled':''}>Siguiente</button></div></div></section>`}
function claimPage(){return `${pageHeader('Siniestros','El estado, los documentos y el próximo paso de cada caso.',button(icon('download')+' Exportar seguimiento','export-claims','light'))}<div class="banner"><div><strong>${S.claims.filter(c=>daysSince(c.lastUpdate)>14).length} casos llevan más de 14 días sin movimiento.</strong><p>El seguimiento se calcula desde el último avance registrado, no desde la fecha del siniestro.</p></div>${icon('shield')}</div><div class="kanban">${['Ingresado','En gestión','Espera aseguradora'].map(st=>`<section class="kanban-col"><div class="kanban-title">${st}<span>${S.claims.filter(c=>c.stage===st).length}</span></div>${S.claims.filter(c=>c.stage===st).map(c=>`<button class="kanban-card" data-action="claim-detail" data-id="${c.id}"><div class="row between">${badge(c.id)}${badge(daysSince(c.lastUpdate)+' días',daysSince(c.lastUpdate)>14?'red':'blue')}</div><h3>${esc(c.client)}</h3><p>${esc(c.type)}</p><span class="company-short">${esc(company(c.company).name)}</span><p>Próximo paso:<br><b>${esc(c.next)}</b></p><span class="small muted" style="font-size:9px">Último avance · ${dateText(c.lastUpdate)}</span></button>`).join('')}</section>`).join('')}</div>`}
function quotePage(){return `${pageHeader('Cotizaciones','Un link para captar la consulta. Una vista para seguirla.',button(icon('link')+' Compartir mi link','share-link','blue'))}<div class="content-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Tu cotizador, con tu nombre</h2>${badge('Daniel Stern · Turi','blue')}</div><p class="small muted">Cotización inicial con pocos datos. Más información permite evaluar mejor el riesgo y las opciones. Sin pedir dos veces lo mismo.</p><div class="row wrap mt24">${button('Probar recorrido del cliente '+icon('arrow'),'test-quote','blue')}${button(icon('copy')+' Copiar link','copy-link','light')}</div><p class="no-claims">Esta demo muestra opciones y precios ficticios. Los casos especiales pasan a revisión del PAS. El link pertenece al productor; no es un negocio B2C independiente.</p></section><section class="panel"><div class="panel-head"><h2>Borradores para revisar</h2>${badge(S.drafts.filter(d=>d.status==='pending').length+' pendientes','yellow')}</div>${S.drafts.length?`<div class="table-wrap"><table><thead><tr><th>Solicitud</th><th>Seguro</th><th>Estado</th><th></th></tr></thead><tbody>${S.drafts.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${d.id}</small></td><td>${esc(d.category)}</td><td>${badge(d.status==='pending'?'Pendiente de aprobación':'Aprobado · demo',d.status==='pending'?'yellow':'green')}</td><td><button class="text-btn" data-action="draft-detail" data-id="${d.id}">Revisar</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('file')}Todavía no hay borradores.<p class="small">Probá el cotizador para crear uno.</p></div>`}</section></div><aside class="stack"><section class="panel" style="background:#f9f1e8"><h2 style="font-size:23px">Tus expertos hacen la diferencia.</h2><p class="small muted mt16">La tecnología prepara la información. Vos aportás experiencia, criterio y la aprobación final.</p><p class="no-claims">No hay una aprobación adicional rutinaria de Admin Turi sobre tu operación.</p></section><section class="panel"><h3>Casos que necesitan una mirada</h3><p class="small muted mt16">0 km, modelos fuera de catálogo, vehículos antiguos y riesgos complejos. Se conserva la consulta y se pide lo necesario, sin descartar al cliente.</p></section></aside></div>`}
function clientsPage(){return `${pageHeader('Mis clientes','Información reunida y vinculada a cada póliza.',button(icon('download')+' Exportar clientes','export-clients','light'))}<div class="panel"><div class="toolbar"><input class="search-input" id="client-search" aria-label="Buscar cliente" placeholder="Buscá por nombre o apellido"></div><div id="clients-list">${clientRows('')}</div></div>`}
function clientRows(q){const cs=S.clients.filter(c=>c.name.toLowerCase().includes(q.toLowerCase())).slice(0,25);return `<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Contacto de muestra</th><th>Pólizas</th><th>Marketing</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${c.id}</small></td><td>${esc(c.email)}</td><td>${S.policies.filter(p=>p.clientId===c.id).length}</td><td>${badge(c.marketing?'Consentimiento de muestra':'Sin consentimiento',c.marketing?'green':'')}</td><td><button class="text-btn" data-action="client-detail" data-id="${c.id}">Ver ficha</button></td></tr>`).join('')}</tbody></table></div><p class="no-claims">Se muestran hasta 25 coincidencias. Los contactos @example.com son ficticios.</p>`}
function adminPage(){const paid=S.policies.slice(0,18).map((p,i)=>({...p,commission:12000+i*1570,retention:450+i*70,invoice:'FC-DEMO-'+(100+i),reviewed:S.tasks[0].done}));const sum=k=>paid.reduce((s,p)=>s+p[k],0);return `${pageHeader('Administración','Tu actividad, tus comprobantes y los controles del mes.',button(icon('download')+' Exportar resumen','export-admin','light'))}<div class="stats">${stat('Comisiones · muestra',money(sum('commission')),'Liquidaciones de octubre · ejemplo','wallet','blue')}${stat('Retenciones · muestra',money(sum('retention')),'Importes ficticios para conciliar','file')}${stat('Neto · muestra',money(sum('commission')-sum('retention')),'Comisiones menos retenciones','chart','blue')}${stat('Controles pendientes',S.tasks.filter(t=>!t.done).length,'Agenda administrativa de ejemplo','calendar','peach')}</div><div class="tabs">${[['resumen','Vista general'],['comisiones','Comisiones y facturación'],['vencimientos','Agenda y controles'],['registros','Registros y rúbrica']].map(([id,t])=>`<button class="tab ${adminTab===id?'active':''}" data-admin-tab="${id}">${t}</button>`).join('')}</div>${adminTab==='comisiones'?`<section class="panel"><div class="panel-head"><h2>Liquidaciones para conciliar</h2>${badge('Importes ficticios')}</div><div class="table-wrap"><table><thead><tr><th>Compañía</th><th>Comprobante de muestra</th><th>Comisión</th><th>Retención</th><th>Neto</th></tr></thead><tbody>${paid.map(p=>`<tr><td>${esc(company(p.company).name)}</td><td>${p.invoice}</td><td>${money(p.commission)}</td><td>${money(p.retention)}</td><td>${money(p.commission-p.retention)}</td></tr>`).join('')}</tbody></table></div></section>`:adminTab==='registros'?`<section class="panel"><h2>Documentación ordenada para tu control</h2><p class="small muted mt16">Documentos, registros y exportaciones en una misma carpeta. Esta demo no presenta rúbricas ni declaraciones.</p><div class="document-list mt24">${['Registro de operaciones · ejemplo','Registro de cobranzas y rendiciones · ejemplo','Carpeta de comprobantes · ejemplo'].map(t=>`<div class="doc-item"><span>${icon('file')} ${t}</span>${button('Ver modelo','registry-model','light small')}</div>`).join('')}</div><div class="row wrap mt24"><a class="btn light small" href="https://www.argentina.gob.ar/ssn" target="_blank" rel="noopener noreferrer">Sitio oficial SSN ${icon('external')}</a></div></section>`:`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>${adminTab==='vencimientos'?'Agenda administrativa':'Tus próximos controles'}</h2>${badge('Octubre · muestra','blue')}</div>${S.tasks.map(t=>`<div class="agenda-line"><span class="agenda-time">${dateText(t.due)}</span><div style="flex:1"><b>${esc(t.title)}</b><p>${esc(t.area)} · fecha de ejemplo</p></div><button class="btn ${t.done?'soft':'light'} small" data-action="task-toggle" data-id="${t.id}">${t.done?icon('check')+' Revisado':'Marcar revisado'}</button></div>`).join('')}<p class="no-claims">Estas fechas organizan el prototipo; no son vencimientos fiscales oficiales. El régimen aplicable se configura y verifica con cada productor.</p></section><aside class="stack"><section class="panel"><h3>Comprobantes y obligaciones</h3><p class="small muted mt16">Facturación, retenciones de IIBB y Convenio Multilateral, con documentación reunida para revisar.</p><div class="stack mt16"><a class="btn light small" href="https://www.arca.gob.ar/" target="_blank" rel="noopener noreferrer">ARCA ${icon('external')}</a><a class="btn light small" href="https://www.ca.gov.ar/" target="_blank" rel="noopener noreferrer">Comisión Arbitral ${icon('external')}</a></div></section><section class="inline-hint">La plataforma prepara y organiza. Las presentaciones fiscales reales requieren reglas verificadas y acceso autorizado.</section></aside></div>`}`}
function marketingPage(){const leads=S.leads;return `${pageHeader('Marketing y ventas','Cada consulta con contexto. Cada oportunidad con un próximo paso.',button(icon('link')+' Mi link de cotización','share-link','blue'))}<div class="tabs">${[['oportunidades','Oportunidades'],['contenido','Contenido y campañas'],['presencia','Mi presencia digital']].map(([id,t])=>`<button class="tab ${marketingTab===id?'active':''}" data-marketing-tab="${id}">${t}</button>`).join('')}</div>${marketingTab==='oportunidades'?`<div class="kanban">${['Nueva consulta','Cotización enviada','Seguimiento'].map(stage=>`<section class="kanban-col"><div class="kanban-title">${stage}<span>${leads.filter(l=>l.stage===stage).length}</span></div>${leads.filter(l=>l.stage===stage).map(l=>`<button class="kanban-card" data-action="lead-detail" data-id="${l.id}"><div class="row between">${badge(l.category,'blue')}${icon('chevron')}</div><h3>${esc(l.name)}</h3><p>Origen · ${esc(l.source)}</p>${badge(l.marketing?'Permite novedades · demo':'Sin permiso de marketing',l.marketing?'green':'')}</button>`).join('')}</section>`).join('')}</div>`:marketingTab==='contenido'?`<div class="marketing-grid"><section class="panel"><h2>Tu mensaje, con el estilo de Turi</h2><p class="small muted mt16">Plantilla de muestra para revisar y adaptar antes de publicar.</p><form id="campaign-form" class="stack mt24"><label class="field">Tema<select name="topic"><option>Hogar</option><option>Autos</option><option>Caución</option><option>Accidentes personales</option></select></label><label class="field">Canal<select name="channel"><option>Instagram</option><option>Facebook</option><option>WhatsApp</option><option>Email</option></select></label><button class="btn blue" type="submit">${icon('spark')} Preparar borrador</button></form><div class="inline-hint mt24">No se envían campañas ni mensajes desde esta demo. El permiso para marketing es independiente de una consulta de seguro.</div></section><section class="panel"><div class="panel-head"><h2>Vista previa de una pieza</h2>${badge('Plantilla')}</div><div class="sample-post">${img('assets/logo.png','Turi','brand-logo')}<h2>Tu casa.<br>Tu tranquilidad.</h2><span class="small">Hacelo simple, hacelo Turi.</span></div><p class="no-claims">Base visual para trabajar con una persona responsable de comunicación.</p></section></div>`:`<section class="panel"><div class="row between wrap"><div><h2>Tu espacio como productor</h2><p class="small muted mt16">Daniel Stern · Turi · cotizador y atención experta.</p></div>${img('assets/daniel.webp','Daniel Stern','avatar lg')}</div><div class="inline-hint mt24">Tu link dirige cada solicitud al perfil del productor, con el origen de la consulta y las preferencias de contacto.</div><div class="row wrap mt24">${button(icon('copy')+' Copiar mi link','copy-link','blue')}${button('Ver mi formulario','test-quote','light')}</div></section>`}`}
const providers=[{id:'chatgpt',name:'ChatGPT',description:'Contexto y herramientas mediante una integración autorizada.',url:'https://platform.openai.com/docs/overview'},{id:'claude',name:'Claude',description:'Documentos y operación con permisos definidos.',url:'https://platform.claude.com/docs/en/home'},{id:'gemini',name:'Gemini',description:'Asistencia contextual a través de su API.',url:'https://ai.google.dev/gemini-api/docs'},{id:'copilot',name:'Copilot',description:'Conexión a evaluar mediante Copilot Studio.',url:'https://learn.microsoft.com/es-es/microsoft-copilot-studio/'}];
function agentPage(){return `${pageHeader('Tu Agente Turi','Un compañero que trabaja con el contexto de tu perfil.',button(icon('settings')+' Elegir mi IA','providers','light'))}<div class="chat-layout"><section class="panel chat-panel"><div class="chat-head">${img('assets/agente-turi.webp','Avatar de Agente Turi','agent-avatar')}<div><h2>Turi · tu operación, más simple</h2><p>Daniel Stern · cartera y documentos de muestra</p></div>${badge('Demo de agente','blue')}</div><div class="chat-messages" id="chat-messages"><div class="message">Hola, Dani. Tengo a mano tu cartera de muestra y tus criterios de seguimiento. ¿Preparamos el día?<small>Respuesta de muestra · sin LLM conectado</small></div>${S.chat.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text)}${m.role==='assistant'?'<small>Fuentes: '+esc(m.sources||'perfil y cartera de muestra')+' · lógica de demo</small>':''}</div>`).join('')}</div><div class="chat-quick"><button data-prompt="Prepará mi día">Prepará mi día</button><button data-prompt="¿Qué siniestros llevan más de 14 días sin novedades?">Siniestros sin novedades</button><button data-prompt="¿Qué pólizas debo renovar?">Próximas renovaciones</button><button data-prompt="Prepará un mensaje para María López">Prepará un mensaje</button></div><form class="chat-form" id="chat-form"><button type="button" class="icon-btn" data-action="upload-doc" aria-label="Adjuntar un documento al contexto">${icon('attachment')}</button><input name="message" required maxlength="2000" aria-label="Mensaje para el agente" placeholder="Preguntale a Turi sobre tu día…" autocomplete="off"><button type="submit" class="btn blue">${icon('arrow')}<span class="small">Enviar</span></button></form></section><aside><section class="panel"><div class="panel-head"><h2>Tu contexto</h2>${icon('file')}</div><div class="document-list">${S.documents.map(d=>`<div class="doc-item"><span style="min-width:0;overflow-wrap:anywhere">${esc(d.name)}<small class="muted" style="display:block;font-size:9px">${esc(d.kind)}</small></span>${d.text?`<button class="text-btn" data-action="doc-detail" data-id="${d.id}">Ver</button>`:''}</div>`).join('')}</div><button class="text-btn mt16" data-action="upload-doc">${icon('upload')} Agregar documento</button><p class="no-claims">En esta demo se lee texto .txt. Los PDF e imágenes quedan como adjuntos de muestra, sin extracción automática.</p></section><section class="panel mt16" style="background:#f9f0e8"><h3>¿Ya trabajás con una IA?</h3><p class="small muted mt16">Elegí tu proveedor y conocé los pasos para conectarlo. Podés exportar el contexto de muestra y probarlo en tu herramienta.</p><div class="stack mt16">${button('Elegir mi IA','providers','light small')}${button('Exportar contexto','export-context','soft small')}</div></section><div class="inline-hint mt16">Una respuesta contextual sigue necesitando fuentes y permisos. El agente prepara acciones; vos conservás el control.</div></aside></div>`}
function providersView(){return `<p>La conexión debe autorizar acceso al contexto de tu perfil y a las herramientas que decidas habilitar.</p><div class="provider-grid mt24">${providers.map(p=>`<div class="provider">${img('assets/providers/'+p.id+'.ico',p.name)}<div class="provider-name">${p.name}</div><p>${p.description}</p>${badge(S.preferences.provider===p.id?'Preferido · demo':'Sin conectar',S.preferences.provider===p.id?'blue':'')}<button class="btn light small" data-action="provider-detail" data-id="${p.id}">Ver integración</button></div>`).join('')}</div><div class="inline-hint mt24">Una suscripción de chat no da acceso automático a la API. La conexión, los permisos y el consumo se evalúan según cada proveedor. Esta demo no pide claves ni conecta cuentas reales.</div>`}
const courses=[{id:'inicio',title:'Tu primera jornada con Turi',time:'8 min',icon:'grid',desc:'Alertas, cartera y próximos pasos, sin saltar entre ventanas.',lessons:[['1 · Priorizá tu día','Abrí Mi día. Rojo indica acción hoy; amarillo, seguimiento próximo; verde, información. Entrá en Resolver para revisar la fuente y preparar la acción.'],['2 · Conservá el contexto','Desde una póliza podés consultar el riesgo, los datos de contacto y su historial. Registrar una gestión actualiza tu seguimiento de muestra, sin ejecutar acciones en una aseguradora.'],['3 · Cerrá el circuito','Cuando terminás una revisión, marcá la alerta como resuelta o posponela. Cada gestión conserva un registro en la actividad del perfil.']]},{id:'ia',title:'Cómo potenciar tu día con tu Agente Turi',time:'12 min',icon:'spark',desc:'Contexto, documentos y herramientas para una ayuda útil.',lessons:[['1 · Un agente necesita más que un chat','Un agente puede usar un modelo de lenguaje, el contexto del productor y herramientas autorizadas. No alcanza con sumar un cuadro de conversación: debe consultar fuentes y preparar acciones comprobables.'],['2 · Elegí cómo usar tu IA','En Agente Turi → Elegir mi IA podés revisar los proveedores. La primera alternativa de prueba es exportar un contexto de muestra. Una integración real requiere API o conectores compatibles, permisos, un servidor y presupuesto.'],['3 · Cargá y verificá documentos','Adjuntá un .txt ficticio en la demo. Preguntá por su contenido y revisá la fuente. La futura lectura de PDF deberá extraer datos, indicar dudas y pedir confirmación cuando corresponda. No cargues datos reales en este prototipo.']]},{id:'cotizar',title:'De la consulta al borrador',time:'10 min',icon:'link',desc:'Un formulario sencillo que reúne lo que necesitás.',lessons:[['1 · Compartí tu link','Copiá Mi link de cotización. El cliente puede ver un ejemplo con datos mínimos del bien. El recorrido pertenece al productor y conserva el origen de la consulta.'],['2 · Permití avanzar con pocos datos','Nombre y edad no se piden para ver el ejemplo inicial. Más información puede ser indispensable para una cotización real según la compañía. Los modelos fuera de catálogo se derivan a revisión experta.'],['3 · Aprobá con la información a mano','El cliente deja su contacto y su intención. El borrador muestra Pendiente de aprobación y no acredita cobertura. Desde Cotizaciones, el PAS revisa datos, documentos, aceptación y pago antes de una aprobación simulada.']]},{id:'negocio',title:'Tu negocio, más ordenado',time:'9 min',icon:'briefcase',desc:'Administración, oportunidades y comunicación con criterio.',lessons:[['1 · Reuní tu información contable','Administración muestra comisiones, retenciones y comprobantes ficticios. Usá la agenda para organizar controles. Los vencimientos y reglas fiscales reales se validarán por régimen y jurisdicción.'],['2 · Cada lead tiene un próximo paso','En Marketing y ventas revisá nuevas consultas, propuestas y seguimientos. No descartes un caso por su valor: reuní el contexto y definí una atención proporcional al trabajo necesario.'],['3 · Revisá antes de publicar','Prepará un texto con la plantilla de Turi. La persona responsable revisa precisión, coberturas e identidad. El permiso de marketing es separado; esta demo no envía ni publica mensajes.']]}];
function trainingPage(){return `${pageHeader('Aprendé a hacerlo simple','Guías breves para trabajar con Turi, a tu ritmo.',button('Consultoría para agencias y brokers','consulting','light'))}<div class="course-grid">${courses.map(c=>`<article class="course"><div class="course-head">${icon(c.icon)}${badge(c.time+' · guía interactiva')}</div><div class="course-body"><h2 style="font-size:23px">${c.title}</h2><p>${c.desc}</p>${c.lessons.map(([t,b])=>`<details class="lesson"><summary>${t}</summary><p>${b}</p></details>`).join('')}<button class="btn ${S.preferences.courses.includes(c.id)?'soft':'light'} small mt16" data-action="course-toggle" data-id="${c.id}">${S.preferences.courses.includes(c.id)?icon('check')+' Guía completada':'Marcar como completada'}</button></div></article>`).join('')}</div><div class="banner mt24"><div><strong>Consultoría para agencias y brokers</strong><p>Relevamiento de procesos, agentes con contexto, capacitación y acompañamiento. Alcance a definir con cada equipo.</p></div>${button('Ver propuesta','consulting','light small')}</div>`}
function accessPage(){return `${pageHeader('Mis accesos','Tus compañías. Tus códigos. Tu entorno de trabajo.')}<div class="inline-hint mb16">En esta demo los botones abren portales o páginas oficiales en otra pestaña. No hay inicio de sesión único ni envío automático de tus credenciales.</div><div class="panel"><div class="panel-head"><h2>15 compañías en tu escritorio</h2>${badge('Códigos de muestra')}</div><div class="stack">${S.companies.map(c=>`<div class="connection-row"><div class="row" style="flex:1">${c.logo?img(c.logo,c.name):`<b style="width:100px">${esc(c.name)}</b>`}<div><b class="small">${esc(c.name)}</b><small>Código PAS · ${esc(c.code)}</small></div></div>${badge(c.portalKind)}<a class="btn light small" href="${esc(c.portal)}" target="_blank" rel="noopener noreferrer">Abrir acceso ${icon('external')}</a><button class="icon-btn" data-action="connection-detail" data-id="${c.id}" aria-label="Ver conexión de ${esc(c.name)}">${icon('settings')}</button></div>`).join('')}</div><p class="no-claims">Selección ilustrativa, sin ranking de mercado. La autorización de integración se valida compañía por compañía y no altera la atribución al PAS.</p></div>`}
function settingsPage(){return `${pageHeader('Mi perfil y respaldo','Tu información y las opciones de esta demo.')}<div class="content-grid"><section class="panel"><div class="row">${img('assets/daniel.webp','Daniel Stern','avatar lg')}<div><h2>Daniel Stern</h2><p class="small muted">Organización · Turi</p>${badge('Productor asesor · perfil de muestra','blue')}</div></div><dl class="detail-grid"><div><dt>Pólizas activas</dt><dd>230</dd></div><div><dt>Compañías del prototipo</dt><dd>15</dd></div><div><dt>Identidad de demo</dt><dd>Dani</dd></div><div><dt>Proveedor IA preferido</dt><dd>${esc(providers.find(p=>p.id===S.preferences.provider)?.name||'Por elegir')} · sin conectar</dd></div></dl><h3>Conservá tus cambios de muestra</h3><p class="small muted mt16">Los estados se guardan en este navegador. Podés exportarlos o restaurar una copia del prototipo.</p><div class="row wrap mt16">${button(icon('download')+' Exportar demo','backup','blue')}${button(icon('upload')+' Restaurar demo','restore','light')}${button('Reiniciar datos','reset','danger')}</div><p class="no-claims">Dani / 1234 es un acceso de demostración visible en el código. No protege información real. La autenticación, el aislamiento de productores y el respaldo del servicio se implementarán antes del piloto.</p></section><aside class="panel"><h3>Actividad reciente de la demo</h3><div class="timeline mt24">${S.activity.slice(0,8).map(a=>`<p>${esc(a.action)}<small>${esc(a.record)} · ${new Date(a.at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}</small></p>`).join('')||'<p>Las acciones que registres aparecerán acá.</p>'}</div></aside></div>`}
const categories=[['Autos','car'],['Motos','car'],['Hogar','home'],['Caución','file'],['Comercio','briefcase'],['Accidentes personales','shield'],['Vida','heart'],['ART','users'],['Responsabilidad civil','shield'],['Agro','home'],['Viajes','briefcase'],['Otros seguros','file']];
function quoteUrl(category){return location.href.split('#')[0]+'#cotizar/daniel-stern'+(category?'?ramo='+encodeURIComponent(category):'')}
function quoteInput(label,name,type='text',required=false,help='',attrs=''){return `<label class="field">${label}${required?' *':''}<input name="${name}" type="${type}" value="${esc(Q[name]||'')}" ${required?'required':''} ${attrs}>${help?`<small>${help}</small>`:''}</label>`}
function riskFields(){if(['Autos','Motos'].includes(Q.category))return `<div class="form-grid">${quoteInput('Marca','brand','text',true,'Por ejemplo, Toyota.','maxlength="60"')}${quoteInput('Modelo y versión','model','text',true,'Si no lo encontrás, describilo.','maxlength="100"')}${quoteInput('Año','year','number',true,'Incluí también los vehículos 0 km.','min="1900" max="2027"')}${quoteInput('Código postal donde se guarda','postal','text',true,'Permite ubicar el riesgo.','inputmode="numeric" pattern="[0-9]{4}" maxlength="4"')}<label class="field">Uso<select name="usage"><option ${Q.usage==='Particular'?'selected':''}>Particular</option><option ${Q.usage==='Comercial'?'selected':''}>Comercial</option><option>Transporte de personas</option></select></label><label class="field">Situación del vehículo<select name="vehicleStatus"><option>Usado / en circulación</option><option>0 km</option><option>Modelo fuera de catálogo</option></select></label></div>`;const main=Q.category==='Hogar'?'Tipo de vivienda':Q.category==='Comercio'?'Actividad del comercio':Q.category==='Caución'?'Tipo de garantía':Q.category==='Accidentes personales'?'Actividad a cubrir':'¿Qué necesitás asegurar?';return `<div class="form-grid">${quoteInput(main,'description','text',true,'Una descripción breve para empezar.','maxlength="250"')}${quoteInput('Código postal del riesgo','postal','text',true,'Ubicación aproximada.','pattern="[0-9]{4}" maxlength="4" inputmode="numeric"')}<label class="field full">Algo que debamos saber<textarea name="extra" maxlength="1500" placeholder="Podés agregar detalles; es opcional.">${esc(Q.extra||'')}</textarea><small>No incluyas datos sensibles.</small></label></div>`}
function isManual(){return !['Autos','Motos','Hogar','Accidentes personales'].includes(Q.category)||(['Autos','Motos'].includes(Q.category)&&(Number(Q.year)<1996||Q.vehicleStatus==='Modelo fuera de catálogo'||/fuera de|otro|f178|f-?100/i.test(Q.model)||Q.usage!=='Particular'))}
function offers(){const x=Q.category==='Hogar'?9500:Q.category==='Accidentes personales'?6000:Q.category==='Motos'?12900:24500;return [{id:'basica',title:'Alternativa A · protección básica',price:x,coverage:'Ejemplo de cobertura básica',details:['Alcance básico de muestra','Condiciones y sumas pendientes de validar'],deductible:'A confirmar en una cotización real'},{id:'amplia',title:'Alternativa B · protección ampliada',price:Math.round(x*1.38),coverage:'Ejemplo de cobertura ampliada',details:['Alcance ampliado de muestra','No equivale a condiciones de ninguna compañía'],deductible:'Franquicia ilustrativa: a confirmar'},{id:'integral',title:'Alternativa C · protección integral',price:Math.round(x*1.91),coverage:'Ejemplo de cobertura integral',details:['Alcance integral de muestra','La elegibilidad depende de evaluar el riesgo'],deductible:'Franquicia ilustrativa: a confirmar'}]}
function publicHeader(){return `<header class="public-header">${logo()}<div class="row gap8">${role==='productor'?button('Volver a mi gestión','back-office','light small'):button('Inicio','entry','light small')}${button(icon('chat')+' Quiero que un experto humano me asesore','human-help','light small')}</div></header>`}
function quoteView(){return `<div class="public">${publicHeader()}<main id="main" class="quote-wrap"><div class="quote-intro"><div><div class="eyebrow">Tu seguro, con la experiencia de Turi</div><h1 class="mt16">Contanos qué querés cuidar.</h1><p>Podés empezar con pocos datos. Nuestros expertos hacen la diferencia al ayudarte a elegir.</p></div><div class="adviser">${img('assets/daniel.webp','Daniel Stern, tu productor','avatar lg')}<div><b>Daniel Stern</b><p>Tu productor · Turi</p></div></div></div><div class="steps" aria-label="Progreso de cotización">${['Tu necesidad','Alternativas','Revisión'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${quoteStep>=i+1?'active':''}" ${quoteStep===i+1?'aria-current="step"':''}><b>${i+1}</b>${s}</span>`).join('')}</div><div class="quote-layout"><section class="panel quote-panel">${quoteStep===1?`<h2>Empecemos por lo que necesitás.</h2><p>Los campos con * son el mínimo para preparar este ejemplo. No necesitás dar nombre, edad ni DNI para verlo.</p><div class="quote-categories">${categories.map(([n,ic])=>`<button class="category ${Q.category===n?'active':''}" data-category="${n}">${icon(ic)}<span>${n}</span></button>`).join('')}</div><form id="risk-form">${riskFields()}<div class="inline-hint mt24">Cuantos más datos tengamos sobre el bien y quien lo asegura, mejor podremos ajustar la propuesta. Algunas compañías requieren datos personales para cotizar de verdad.</div><div class="quote-actions"><span class="small muted">Paso 1 de 3 · ${esc(Q.category)}</span><button class="btn blue" type="submit">Ver ejemplo ${icon('arrow')}</button></div></form>`:quoteStep===2?isManual()?`<h2>Este caso merece una mirada experta.</h2><p>Conservamos lo que cargaste. Daniel puede evaluar el riesgo y pedir la información necesaria en un solo paso.</p><div class="inline-hint peach"><b>${esc(Q.category)}</b> · ${esc(Q.model||Q.description||'Caso especial')}<br>No inventamos una tarifa cuando falta una evaluación.</div><p class="small muted mt24">Para vehículos especiales pueden hacer falta fotos, versión, uso y documentación. Podés continuar sin adjuntarlos ahora.</p><div class="quote-actions">${button('Atrás','quote-back','light')}<button class="btn blue" data-action="manual-continue">Enviar a revisión ${icon('arrow')}</button></div>`:`<h2>Así podrías comparar tus alternativas.</h2><p>Ejemplo de interfaz, sin consulta a aseguradoras. Los importes son ficticios y no constituyen una oferta ni una recomendación.</p><div class="quote-offers">${offers().map(o=>`<article class="offer"><div class="row between wrap"><div>${badge('Precio ficticio · ARS/mes','yellow')}<h3 class="mt16">${o.title}</h3></div><div class="price">${money(o.price)}<small> / mes</small></div></div><ul>${o.details.map(t=>`<li>${t}</li>`).join('')}<li>${o.deductible}</li></ul><button class="btn light small" data-action="select-offer" data-id="${o.id}">Continuar con este ejemplo ${icon('arrow')}</button></article>`).join('')}</div><div class="quote-actions">${button('Revisar mis datos','quote-back','light')}<span class="small muted">Sin cobertura emitida.</span></div>`:quoteStep===3?`<h2>Dejemos tu solicitud preparada.</h2><p>La recibe Daniel Stern. Podés elegir contacto humano en cualquier momento.</p><div class="inline-hint mb16">${selectedOffer?esc(selectedOffer.title)+' · '+money(selectedOffer.price)+' ficticios / mes':'Evaluación por un experto'}<br>En Turi valoramos la responsabilidad y el profesionalismo a la hora de asegurar. Por eso operamos con tecnología y supervisión humana.</div><form id="contact-form"><div class="form-grid">${quoteInput('Nombre y apellido','name','text',true,'Para dirigir la solicitud.','maxlength="120"')}${quoteInput('Email','email','email',true,'Usá datos ficticios en esta demo.','maxlength="160"')}${quoteInput('Teléfono de contacto','phone','tel',false,'Opcional si preferís email.','maxlength="30"')}${quoteInput('Fecha de nacimiento','dob','date',false,'Puede ser necesaria para una tarifa real.','max="2026-10-19"')}${quoteInput('DNI / identificación','identity','text',false,'Opcional en la demo. Se validará cuando corresponda.','maxlength="30"')}<label class="field">Preferencia de contacto<select name="contactPreference"><option>Email</option><option>WhatsApp</option><option>Llamada</option></select></label><label class="field full">Instrumento de pago a configurar<select name="payment"><option>Débito a configurar con la compañía</option><option>Tarjeta en sitio seguro de la compañía</option><option>Consultar medios disponibles</option></select><small>No ingreses números de tarjeta, cuentas ni claves. El instrumento se valida en un entorno seguro antes de una operación real.</small></label><label class="field full">Documentos de muestra opcionales<input type="file" name="quoteDocs" id="quote-docs" accept=".pdf,.jpg,.jpeg,.png,.txt" multiple><small>Se conserva el nombre del adjunto en esta demo; no se procesa ni se envía el archivo.</small></label><label class="check full"><input type="checkbox" name="intent" required><span>Quiero que Daniel revise esta solicitud. Entiendo que este ejemplo no es una póliza y no activa cobertura.</span></label><label class="check full"><input type="checkbox" name="marketing" ${Q.marketing?'checked':''}><span>Quiero recibir novedades y propuestas de Turi. Es opcional y no condiciona mi consulta.</span></label></div><div class="quote-actions">${button('Atrás','quote-back','light')}<button class="btn blue" type="submit">Enviar a revisión ${icon('arrow')}</button></div><p class="no-claims">Demo: los datos se guardan solamente en este navegador. No hay envío de correos ni cobro.</p></form>`:quoteSuccess()}</section><aside class="quote-aside"><section class="panel" style="background:#f8f1e8"><h3>Vos elegís cómo avanzar.</h3><p>Podés cargar los datos a tu ritmo o pedir que un experto te acompañe. La información ya cargada queda en tu consulta de muestra.</p>${button('Quiero que un experto humano me asesore','human-help','light')}</section><section class="panel"><h3>Claro desde el principio.</h3><p>Este recorrido prepara un borrador. La póliza real y su vigencia requieren revisión del PAS y aceptación de la aseguradora.</p><p class="mt16">El documento de muestra lleva <b>“Pendiente de aprobación”</b> y <b>“Esto no es una póliza”</b>.</p></section>${demoNote()}</aside></div></main></div>`}
function quoteSuccess(){const d=S.drafts.find(x=>x.id===Q.draftId);return `<div class="success-icon">${icon('check')}</div><h2>Tu solicitud quedó preparada.</h2><p>Daniel tiene tu consulta ordenada para revisar. En esta demo el aviso aparece en su tablero, sin enviar mensajes reales.</p><div class="watermark-preview"><div class="eyebrow">TURI · DOCUMENTO DE MUESTRA</div><h3 class="mt16">${esc(d?.category||Q.category)} · ${esc(d?.name||Q.name)}</h3><p class="mt16">Referencia ${esc(d?.id||'DEMO')}<br>Cobertura no emitida. Esto no es una póliza.<br>La vigencia se confirma con la aseguradora.</p></div><div class="inline-hint mt24">Un asesor te contactará en las próximas 48 hs para avanzar con tu solicitud. El plazo corresponde al contacto, no garantiza la emisión ni activa cobertura. Aviso ilustrativo de este prototipo.</div><div class="row wrap mt24">${button(icon('download')+' Descargar PDF de muestra','download-draft','blue',`data-id="${esc(d?.id||'')}"`)}${role==='productor'?button('Revisar como productor','back-office','light'):button('Volver al inicio','entry','light')}</div>`}
function clientHome(){return `<div class="public">${publicHeader()}<main id="main" class="quote-wrap"><section class="client-hero"><div><div class="eyebrow">Tu espacio de cliente · demo</div><h1 class="mt16">Tu seguro, con alguien que te conoce.</h1><p>Consultá tus documentos, seguí un caso o prepará una nueva consulta con tu productor.</p>${button('Quiero cotizar '+icon('arrow'),'test-quote','blue')}</div><div class="client-profile">${img('assets/daniel.webp','Daniel Stern, productor de Turi','avatar')}<div><h3>Daniel Stern</h3><p style="margin:4px 0;font-size:11px">Tu productor · Organización Turi</p>${badge('Atención experta','blue')}</div></div></section><section class="panel"><div class="panel-head"><h2>Mis seguros · ejemplos</h2>${badge('3 registros ficticios')}</div>${S.policies.slice(0,3).map(p=>`<div class="agenda-line">${icon(p.category==='Hogar'?'home':'car')}<div style="flex:1"><b>${esc(p.category)} · ${esc(p.risk)}</b><p>${esc(company(p.company).name)} · ${p.id}</p></div>${button('Ver resumen','client-policy','light small',`data-id="${p.id}"`)}</div>`).join('')}</section><section class="panel mt24"><h2>¿Necesitás ayuda con un siniestro?</h2><p class="small muted mt16">El acompañamiento del productor está a un clic. En esta demo podés preparar una solicitud de atención.</p><div class="mt16">${button(icon('chat')+' Hablar con un experto','human-help','light')}</div></section><section class="panel mt24"><h2>Conocé el recorrido de tu seguro</h2><div class="row wrap mt24">${Object.keys(insuranceFAQs).map(c=>`<button class="btn light small" data-route="seguros/${encodeURIComponent(c)}">${c} ${icon('arrow')}</button>`).join('')}</div></section><p class="no-claims">Vista de muestra del cliente. No representa pólizas reales ni un negocio B2C independiente.</p></main></div>`}

const insuranceFAQs={
 Autos:[['¿Qué necesito para empezar?','Marca, modelo, año, uso y código postal del lugar donde se guarda el vehículo. En esta demo podés ver un ejemplo sin dar nombre ni edad.'],['¿Por qué pueden pedirme más datos?','Una tarifa real depende del riesgo y de los requisitos de cada compañía. El productor te ayuda a reunirlos antes de solicitar una contratación.'],['¿Qué pasa si mi vehículo no aparece?','La consulta sigue con un experto. Los modelos antiguos o fuera de catálogo no se descartan ni reciben una tarifa inventada.']],
 Hogar:[['¿Qué información conviene reunir?','Tipo y ubicación de la vivienda, uso y descripción de los bienes. El productor completa la evaluación según lo que querés proteger.'],['¿Todas las propuestas cubren lo mismo?','No se debe suponer equivalencia: hay que revisar bienes incluidos, sumas, límites, exclusiones y condiciones de la opción concreta.'],['¿El ejemplo ya asegura mi casa?','No. Prepara una consulta. La cobertura y la vigencia se confirman con la aseguradora después de la revisión.']],
 Caución:[['¿Puedo consultar aunque no sepa si califico?','Sí. La demo conserva tu consulta para que el productor evalúe la garantía y los requisitos aplicables.'],['¿Qué datos se revisan después?','El destino de la garantía y la documentación necesaria para el caso, según la evaluación del productor y de la compañía.'],['¿Esta consulta garantiza la aceptación?','No. La evaluación, la propuesta y la aceptación están pendientes. El formulario no emite una garantía.']],
 'Accidentes personales':[['¿Por qué importa mi actividad?','Para que el productor entienda el riesgo y consulte las condiciones aplicables. Una descripción clara ayuda a preparar mejor la solicitud.'],['¿Puedo pedir ayuda para completar la información?','Sí. El botón de atención humana conserva tu consulta de muestra y la prepara para el productor.'],['¿Cuándo tengo cobertura?','El PDF de ejemplo no acredita seguro. La cobertura y la fecha de vigencia requieren confirmación de la compañía.']]
};
function insurancePage(category){const faqs=insuranceFAQs[category]||insuranceFAQs.Autos;return `<div class="public">${publicHeader()}<main id="main" class="quote-wrap"><div class="quote-intro"><div><div class="eyebrow">Con la experiencia de tu productor</div><h1 class="mt16">${esc(category)}, más simple.</h1><p>Entendé qué información necesitás y prepará tu consulta con Daniel Stern.</p></div>${img('assets/daniel.webp','Daniel Stern, productor de Turi','avatar lg')}</div><div class="quote-layout"><section class="panel"><h2>Antes de empezar</h2><p class="small muted mt16">Tus necesidades y las condiciones de cada propuesta se revisan con criterio experto.</p>${faqs.map(([q,a])=>`<details class="lesson mt16"><summary>${q}</summary><p>${a}</p></details>`).join('')}<div class="inline-hint mt24">Esto es una guía del recorrido de muestra. No describe ni promete condiciones de una póliza real.</div><div class="mt24">${button('Preparar mi consulta '+icon('arrow'),'quote-category','blue',`data-id="${esc(category)}"`)}</div></section><aside class="panel"><h2 style="font-size:24px">La tecnología simplifica. Tu experto acompaña.</h2><p class="small muted mt16">Podés elegir atención personal en cualquier momento. El productor es quien revisa tu solicitud antes de avanzar.</p><div class="mt24">${button('Hablar con un experto','human-help','light small')}</div></aside></div></main></div>`}

function render(){const r=route();const el=$('#app');if(r.startsWith('seguros/')){const c=decodeURIComponent(r.slice(8));el.innerHTML=insurancePage(insuranceFAQs[c]?c:'Autos');return;}if(r.startsWith('cotizar/')){const params=new URLSearchParams(r.split('?')[1]||'');if(params.get('ramo')&&quoteStep===1&&categories.some(c=>c[0]===params.get('ramo')))Q.category=params.get('ramo');el.innerHTML=quoteView();return;}if(r==='cliente'&&role){el.innerHTML=clientHome();return;}if(!role||r==='inicio'){el.innerHTML=entry();return;}if(role==='cliente'){el.innerHTML=clientHome();return;}const pages={tablero:dashboard,polizas:policyList,siniestros:claimPage,cotizaciones:quotePage,clientes:clientsPage,administracion:adminPage,marketing:marketingPage,agente:agentPage,capacitacion:trainingPage,accesos:accessPage,ajustes:settingsPage};el.innerHTML=shell((pages[r]||dashboard)(),pages[r]?r:'tablero');if(r==='agente'){const c=$('#chat-messages');c.scrollTop=c.scrollHeight;}}
function policyDetail(id,customer=false){const p=S.policies.find(p=>p.id===id);if(!p)return;const c=S.clients.find(c=>c.id===p.clientId);modal('Póliza · '+p.id,`${badge('Registro ficticio · no acredita seguro','yellow')}<h3 class="mt24">${esc(p.client)}</h3><p>${esc(p.risk)}</p><dl class="detail-grid"><div><dt>Tipo de seguro</dt><dd>${esc(p.category)}</dd></div><div><dt>Compañía</dt><dd>${esc(company(p.company).name)}</dd></div><div><dt>Vencimiento</dt><dd>${new Date(p.expiry+'T12:00:00').toLocaleDateString('es-AR')} · muestra</dd></div><div><dt>Estado de pago de muestra</dt><dd>${esc(p.payment)}</dd></div><div><dt>Prima ficticia mensual</dt><dd>${money(p.premium)}</dd></div><div><dt>Suma asegurada ficticia</dt><dd>${money(p.sum)}</dd></div><div><dt>Contacto</dt><dd>${esc(c?.email)}</dd></div><div><dt>Responsable</dt><dd>Daniel Stern · ${esc(company(p.company).code||'Código de muestra')}</dd></div></dl><h3>Documentos e historial</h3><div class="doc-item">${icon('file')} Resumen de póliza · modelo ilustrativo ${button('Descargar','download-policy','light small',`data-id="${p.id}"`)}</div><div class="timeline mt24"><p>Registro disponible en la cartera<small>Carga de muestra · no importada de la aseguradora</small></p>${S.activity.filter(a=>a.record===id).slice(0,4).map(a=>`<p>${esc(a.action)}<small>Gestión local de demo</small></p>`).join('')}</div>`,`${button('Cerrar','close-modal','light')}${customer?button('Pedir ayuda','human-help','blue'):button('Preparar mensaje','policy-message','blue',`data-id="${p.id}"`)}`)}
function alertDetail(id){const a=S.alerts.find(a=>a.id===id);if(!a)return;modal('Tu próximo paso',`${badge(a.category,a.priority)}<h3 class="mt24">${esc(a.title)}</h3><p>${esc(a.client)} · ${esc(company(a.company).name)}</p><dl class="detail-grid"><div><dt>Fecha límite</dt><dd>${dateText(a.due)} · jornada de muestra</dd></div><div><dt>Fuente</dt><dd>${esc(a.source)}</dd></div></dl><div class="inline-hint">${esc(a.detail)}</div><div class="row wrap mt24">${a.policyId?button('Ver póliza','policy-detail','light small',`data-id="${a.policyId}"`):''}${a.category==='Siniestros'?button('Abrir siniestro','claim-detail','light small','data-id="SIN-2401"'):''}${a.company?`<a href="${esc(company(a.company).portal)}" class="btn light small" target="_blank" rel="noopener noreferrer">Abrir compañía ${icon('external')}</a>`:''}</div><p class="no-claims">Resolver registra tu gestión en Turi. No confirma un cambio ni realiza una operación en la compañía.</p>`,`${button('Posponer 1 día','alert-snooze','light',`data-id="${id}"`)}${a.policyId?button('Preparar mensaje','alert-message','light',`data-id="${id}"`):''}${button(icon('check')+' Marcar resuelta','alert-done','blue',`data-id="${id}"`)}`)}
function claimDetail(id){const c=S.claims.find(c=>c.id===id);if(!c)return;modal('Seguimiento · '+c.id,`${badge(c.stage,'blue')}<h3 class="mt24">${esc(c.client)}</h3><p>${esc(c.type)} · ${esc(company(c.company).name)}</p><div class="inline-hint ${daysSince(c.lastUpdate)>14?'peach':''} mt16">${daysSince(c.lastUpdate)} días desde el último avance. Próximo paso: ${esc(c.next)}.</div><form id="claim-form" class="stack mt24" data-id="${c.id}"><label class="field">Nuevo estado<select name="stage">${['Ingresado','En gestión','Espera aseguradora'].map(x=>`<option ${x===c.stage?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Avance registrado<textarea name="note" required maxlength="1500" placeholder="Ejemplo: solicité informe de peritación a la compañía."></textarea></label><label class="field">Próximo paso<input name="next" required maxlength="200" value="${esc(c.next)}"></label><button class="btn blue" type="submit">${icon('check')} Registrar avance de muestra</button></form><h3>Historial de seguimiento</h3><div class="timeline mt16"><p>Caso en seguimiento<small>Último avance base · ${dateText(c.lastUpdate)}</small></p>${c.notes.map(n=>`<p>${esc(n.text)}<small>${dateText(n.date)} · Daniel Stern · demo</small></p>`).join('')}</div>`,button('Cerrar','close-modal','light'))}
function messageModal(text,title='Borrador de mensaje'){modal(title,`<p>Revisá y adaptá el texto. No se envía automáticamente.</p><label class="field mt16">Mensaje<textarea id="message-draft" style="min-height:190px" maxlength="6000">${esc(text)}</textarea></label><p class="no-claims">No implica emisión, renovación, baja ni confirmación de cobertura.</p>`,`${button('Cerrar','close-modal','light')}${button(icon('copy')+' Copiar texto','copy-message','blue')}`)}
function prepareMessage(id){const p=S.policies.find(p=>p.id===id);if(!p)return;messageModal(`Hola, ${p.client.split(' ')[0]}. Soy Daniel, de Turi. Estoy revisando tu seguro de ${p.category.toLowerCase()} en ${company(p.company).name}. La fecha de vencimiento que tengo en mi registro de muestra es ${dateText(p.expiry)}. ¿Podemos confirmar si hubo cambios en el bien o en tus necesidades antes de preparar las alternativas?\n\nHacelo simple, hacelo Turi.\n\nTexto de demostración: verificar datos y estado real antes de enviarlo.`)}
function completeAlert(id){const a=S.alerts.find(a=>a.id===id);if(a&&!a.done){a.done=true;a.resolvedAt=new Date().toISOString();audit('Alerta marcada resuelta',a.policyId)}closeModal();render();toast('Gestión registrada en la demo. No se operó en la compañía.')}
function registerClaim(id,{stage,note,next}){const c=S.claims.find(c=>c.id===id);if(!c||!note?.trim()||!next?.trim())return false;c.stage=stage;c.lastUpdate=S.demoDate;c.next=next.trim();c.notes.push({text:note.trim(),date:S.demoDate});S.alerts.filter(a=>a.category==='Siniestros'&&a.policyId===c.policyId).forEach(a=>a.done=true);audit('Avance de siniestro registrado',id);return true;}
function recordDraft(data){if(!data.name?.trim()||!data.email?.trim()||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)||!data.intent)return null;if(data.submissionId&&S.drafts.some(d=>d.submissionId===data.submissionId))return S.drafts.find(d=>d.submissionId===data.submissionId);const id='SOL-'+String(S.drafts.length+1).padStart(4,'0'),draft={...clone(Q),...data,id,producerId:'PAS-DANI',status:'pending',version:1,coverageIssued:false,accepted:true,offer:selectedOffer?clone(selectedOffer):null,createdAt:new Date().toISOString(),paymentVerified:false,identityVerified:false,docsVerified:false,conditionsVerified:false};S.drafts.unshift(draft);S.leads.unshift({id:'L-'+id,name:draft.name,category:draft.category,source:'Link de Daniel',stage:'Nueva consulta',marketing:!!draft.marketing});S.alerts.unshift({id:'AL-'+id,policyId:null,draftId:id,title:'Nueva solicitud para revisar',category:'Actualizaciones',priority:'yellow',company:'segunda',client:draft.name,due:plusDays(S.demoDate,1),source:'Link del productor · demo',detail:'La solicitud está pendiente de la revisión del PAS. No se emitió cobertura.',done:false});audit('Solicitud recibida para revisión',id);return draft;}
function draftDetail(id){const d=S.drafts.find(x=>x.id===id);if(!d)return;modal('Revisión del PAS · '+id,`${badge(d.status==='pending'?'Pendiente de aprobación':'Aprobado · simulación',d.status==='pending'?'yellow':'green')}<h3 class="mt24">${esc(d.name)}</h3><dl class="detail-grid"><div><dt>Contacto</dt><dd>${esc(d.email)}<br>${esc(d.phone||'Sin teléfono')}</dd></div><div><dt>Preferencia</dt><dd>${esc(d.contactPreference||'Email')}</dd></div><div><dt>Riesgo</dt><dd>${esc(d.category)} · ${esc(d.brand||'')} ${esc(d.model||d.description||'')} ${esc(d.year||'')}<br>CP ${esc(d.postal)}</dd></div><div><dt>Alternativa</dt><dd>${esc(d.offer?.title||'Evaluación experta pendiente')}</dd></div><div><dt>Identificación</dt><dd>${esc(d.identity||'No aportada · pendiente validar')}</dd></div><div><dt>Instrumento de pago</dt><dd>${esc(d.payment)}<br>No validado en esta demo</dd></div><div><dt>Documentos</dt><dd>${esc(d.attachments?.join(', ')||'Sin adjuntos · revisar requisitos')}</dd></div><div><dt>Aceptación</dt><dd>${d.accepted?'Intención registrada':'Pendiente'} · versión ${d.version}</dd></div></dl><div class="inline-hint peach">Una sola revisión del PAS responsable, sin aprobación adicional de Admin Turi. La cobertura permanece sin emitir incluso al aprobar esta simulación.</div><form id="approve-form" class="stack mt24" data-id="${id}">${[['identityVerified','Revisé identidad y datos aplicables'],['conditionsVerified','Revisé riesgo, alcance, sumas y condiciones'],['docsVerified','Revisé documentos y requisitos aplicables'],['paymentVerified','Revisé el instrumento de pago de muestra']].map(([k,label])=>`<label class="check"><input name="${k}" type="checkbox" required ${d[k]?'checked':''}><span>${label}</span></label>`).join('')}<button type="submit" class="btn blue" ${d.status!=='pending'?'disabled':''}>Aprobar borrador · simulación</button></form>`,`${button('Cerrar','close-modal','light')}${button(icon('download')+' PDF de muestra','download-draft','light',`data-id="${id}"`)}`)}
function approveDraft(id,checks){const d=S.drafts.find(d=>d.id===id);if(!d||d.status!=='pending'||!d.accepted||!['identityVerified','conditionsVerified','docsVerified','paymentVerified'].every(k=>checks[k]))return false;Object.assign(d,checks,{status:'approved_demo',approvedBy:'Daniel Stern',coverageIssued:false,approvedAt:new Date().toISOString()});S.alerts.filter(a=>a.draftId===id).forEach(a=>a.done=true);audit('Borrador aprobado · simulación sin emisión',id);return true;}
function agentAnswer(prompt){const n=prompt.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let text='',sources='';if(/siniestro|14 dias|novedad/.test(n)){const cs=S.claims.filter(c=>daysSince(c.lastUpdate)>14);text=cs.length?`Encontré ${cs.length} siniestros con más de 14 días sin movimiento:\n\n${cs.map(c=>`${c.client} · ${c.id}\n${daysSince(c.lastUpdate)} días · ${company(c.company).name}\nPróximo paso: ${c.next}.`).join('\n\n')}\n\nPodés abrir Siniestros para registrar el avance. No hice consultas ni envié mensajes a las compañías.`:'Todos los siniestros de la muestra tienen avances registrados dentro de los últimos 14 días.';sources='siniestros del perfil + guía de operación';}else if(/renova|poliza|vencim/.test(n)){const ps=S.policies.filter(p=>p.expiry<=plusDays(S.demoDate,7));text=`Hay ${ps.length} pólizas de muestra con vencimiento dentro de 7 días.\n\n${ps.slice(0,5).map(p=>`${p.client} · ${company(p.company).name} · ${dateText(p.expiry)}`).join('\n')}\n\nAntes de comunicar una renovación, verificá vigencia, condiciones, suma asegurada e instrumento de pago en la compañía. Puedo preparar el texto, sin enviarlo.`;sources='cartera de 230 pólizas ficticias';}else if(/mensaje|maria/.test(n)){text='Borrador para revisar:\n\nHola, María. Soy Daniel, de Turi. Estoy revisando la próxima renovación de tu seguro. ¿Hubo cambios en el bien o en lo que necesitás proteger? Voy a verificar las condiciones antes de prepararte las alternativas.\n\nEste mensaje es de muestra. No fue enviado y no confirma cobertura.';sources='póliza POL-100001 + criterio de revisión del perfil';}else if(/dia|prioridad|urgente/.test(n)){const urgent=S.alerts.filter(a=>!a.done&&a.priority==='red');text=`Dani, empezaría por ${urgent.length?urgent.map(a=>a.client+': '+a.title.toLowerCase()).join('; '):'revisar las próximas fechas'}.
\nDespués miraría los siniestros sin avances y el control de comisiones de octubre. Hay ${S.alerts.filter(a=>!a.done).length} alertas pendientes en tu bandeja.\n\nPuedo preparar textos y reunir datos. Las decisiones aseguradoras las confirmás vos.`;sources='alertas, siniestros y tareas administrativas del perfil';}else if(/comision|impuesto|contab|retencion/.test(n)){text='Tu carpeta administrativa de muestra incluye liquidaciones de comisiones, retenciones de IIBB, comprobantes y un control para Convenio Multilateral.\n\nAbrí Administración para conciliar y exportar. Las fechas son ilustrativas; no calculé ni presenté impuestos. Las reglas reales deberán validarse con tu régimen, jurisdicciones y documentación.';sources='agenda administrativa de muestra';}else{const terms=n.split(/\W+/).filter(t=>t.length>3);const docs=S.documents.filter(d=>d.text&&terms.some(t=>d.text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(t)));if(docs.length){text=`Encontré información relacionada en ${docs.map(d=>d.name).join(', ')}:\n\n${docs.slice(0,2).map(d=>d.text.slice(0,800)).join('\n\n')}\n\nEs texto del contexto cargado; no verifiqué condiciones con una aseguradora.`;sources=docs.map(d=>d.name).join(', ')}else{text='En esta demo puedo ayudarte a priorizar el día, ver renovaciones, encontrar siniestros sin movimiento, preparar un mensaje y consultar textos .txt cargados en tu perfil.\n\nPara resolver consultas abiertas y ejecutar herramientas hace falta conectar un proveedor de IA con permisos. Esta respuesta usa reglas de muestra y los registros del prototipo.';sources='alcance del asistente de demostración'}}return {text,sources};}
function sendChat(prompt){if(!prompt?.trim())return;S.chat.push({role:'user',text:prompt.trim().slice(0,2000)});S.chat.push({role:'assistant',...agentAnswer(prompt)});save();if(route()!=='agente')navigate('agente');else render();}
function pdfEscape(s){let out='';for(const c of String(s)){const n=c.charCodeAt(0);if(c==='\\'||c==='('||c===')')out+='\\'+c;else if(n>=32&&n<=126)out+=c;else if(n<=255)out+='\\'+n.toString(8).padStart(3,'0');else out+='-';}return out;}
function makePDF(title,lines){const wrap=s=>String(s).match(/.{1,85}(?:\s|$)|.{1,85}/g)||[''];const body=lines.flatMap(wrap).slice(0,32);let stream='0.94 0.92 0.89 rg 0 0 595 842 re f\n1 1 1 rg 32 62 531 744 re f\n0.16 0.24 0.28 rg\nBT /F1 25 Tf 48 770 Td (TURI GESTION) Tj ET\n';stream+=`BT /F1 14 Tf 48 733 Td (${pdfEscape(title)}) Tj ET\n`;body.forEach((l,i)=>{stream+=`BT /F1 10 Tf 48 ${690-i*16} Td (${pdfEscape(l)}) Tj ET\n`});stream+='q 0.85 0.75 0.72 rg 0.94 0.34 -0.34 0.94 65 340 cm BT /F1 25 Tf 0 0 Td (PENDIENTE DE APROBACION) Tj ET Q\n';stream+='0.65 0.22 0.2 rg BT /F1 12 Tf 48 114 Td (ESTO NO ES UNA POLIZA - DEMO ILUSTRATIVO) Tj ET\n';stream+='0.2 0.25 0.28 rg BT /F1 8 Tf 48 94 Td (Cobertura no emitida. No acredita seguro ni activa vigencia.) Tj ET\nBT /F1 8 Tf 48 79 Td (Requiere revision del PAS y aceptacion de la aseguradora.) Tj ET\n';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',`<< /Length ${stream.length} >>\nstream\n${stream}endstream`];let pdf='%PDF-1.4\n';const offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`});const start=pdf.length;pdf+=`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;return new Uint8Array([...pdf].map(c=>c.charCodeAt(0)));}
function download(name,content,type='text/plain;charset=utf-8'){const b=new Blob([content],{type});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function csv(rows){const cell=x=>{let s=String(x??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};return '\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')}
async function copy(t){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(t);toast('Copiado.')}else{modal('Texto para copiar',`<label class="field">Seleccioná y copiá<textarea id="copy-fallback" readonly>${esc(t)}</textarea></label>`,button('Cerrar','close-modal','light'));$('#copy-fallback').select();}}catch{modal('Copiar manualmente',`<textarea class="search-input" readonly>${esc(t)}</textarea>`,button('Cerrar','close-modal','light'));}}
function shareLink(){modal('Tu link de cotización',`<div class="row">${img('assets/daniel.webp','Daniel Stern','avatar')}<div><b>Daniel Stern · Turi</b><p>La consulta queda vinculada a tu perfil.</p></div></div><label class="field mt24">Link del formulario<input id="share-url" readonly value="${esc(quoteUrl())}"></label><label class="field mt16">Seguro inicial<select id="share-category"><option value="">Todos los seguros</option>${categories.map(([c])=>`<option>${c}</option>`).join('')}</select></label><div class="inline-hint mt24">Podés compartir este enlace para probar el recorrido sin cuenta de ChatGPT. Es una demo con datos ficticios; los cambios y solicitudes se guardan sólo en el navegador de quien la utiliza.</div>`,`${button('Probar recorrido','test-quote','light')}${button(icon('copy')+' Copiar link','copy-share','blue')}`)}
function captureQuoteFields(){const f=$('#risk-form')||$('#contact-form');if(f){for(const [k,v] of new FormData(f))if(typeof v==='string')Q[k]=v;if(f.elements.marketing)Q.marketing=f.elements.marketing.checked;}}
function humanHelp(){captureQuoteFields();modal('Un experto te acompaña',`<div class="row">${img('assets/daniel.webp','Daniel Stern','avatar lg')}<div><h3>Daniel Stern</h3><p>Organización · Turi</p></div></div><p class="mt24">Podés salir del recorrido automático. Dejamos tu necesidad y los datos cargados preparados para atención personal.</p><form id="human-form" class="stack mt24"><label class="field">Tu nombre<input name="name" required value="${esc(Q.name)}" maxlength="120"></label><label class="field">Email para contactarte<input name="email" type="email" required value="${esc(Q.email)}" maxlength="160"></label><label class="field">¿En qué necesitás ayuda?<textarea name="need" required maxlength="1500">${esc(Q.category+' · '+(Q.model||Q.description||''))}</textarea></label><button class="btn blue" type="submit">Preparar consulta para Daniel</button></form><p class="no-claims">Se registra una solicitud de muestra en este navegador. No se envían mensajes reales.</p>`,button('Cerrar','close-modal','light'))}
function providerDetail(id){const p=providers.find(p=>p.id===id);if(!p)return;modal('Integrar '+p.name,`<h3>Un camino simple para empezar</h3><p>1. Exportá el contexto ficticio de esta demo y revisalo.<br>2. Abrí tu herramienta de IA y usalo como material de referencia.<br>3. Para operar desde Turi, definimos una conexión mediante API o conectores compatibles.</p><h3>La conexión profesional</h3><p>Autorización del productor, contexto limitado a su cartera, documentos con acceso controlado, herramientas habilitadas y registro de acciones. Las claves se guardan en servidor; nunca se cargan en esta maqueta.</p><div class="inline-hint mt16">${p.name==='Copilot'?'Copilot Studio y los conectores requieren evaluar licencias, capacidades y permisos del entorno.':'La suscripción de chat y el consumo de API pueden tener facturación y límites diferentes.'} No hay conexión activa en este prototipo.</div><a class="btn light small mt24" href="${p.url}" target="_blank" rel="noopener noreferrer">Documentación oficial ${icon('external')}</a>`,`${button('Exportar contexto de prueba','export-context','light')}${button('Elegir como preferido · demo','provider-select','blue',`data-id="${id}"`)}`)}
function pickFile(accept,fn){const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',()=>{if(input.files[0])fn(input.files[0])});input.click();}
function recordDocument(file){if(file.size>5*1024*1024){toast('Usá un archivo de muestra de hasta 5 MB.');return;}const d={id:'DOC-'+Date.now(),name:file.name.slice(0,180),kind:'Adjunto local de muestra',text:''};if(/\.txt$/i.test(file.name)){file.text().then(t=>{d.kind='Texto local de muestra';d.text=t.slice(0,16000);S.documents.push(d);audit('Documento de contexto agregado',d.id);render();toast('Texto agregado al contexto de la demo.');}).catch(()=>toast('No se pudo leer el archivo.'));}else{S.documents.push(d);audit('Referencia de adjunto agregada',d.id);render();toast('Nombre del adjunto agregado. El contenido PDF/imagen no se procesa en esta demo.');}}
function leadDetail(id){const l=S.leads.find(l=>l.id===id);if(!l)return;modal('Oportunidad · '+l.name,`${badge(l.category,'blue')}<p class="mt16">Origen: ${esc(l.source)}<br>Consentimiento de marketing: ${l.marketing?'sí · muestra':'no'}</p><form id="lead-form" class="stack mt24" data-id="${id}"><label class="field">Próximo estado<select name="stage">${['Nueva consulta','Cotización enviada','Seguimiento'].map(x=>`<option ${l.stage===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Nota para mi seguimiento<textarea name="note" maxlength="1000">${esc(l.note||'')}</textarea></label><button type="submit" class="btn blue">Guardar seguimiento</button></form>`,button('Cerrar','close-modal','light'))}
document.addEventListener('click',e=>{const routeEl=e.target.closest('[data-route]');if(routeEl){navigate(routeEl.dataset.route);return;}const filter=e.target.closest('[data-filter]');if(filter){activeFilter=filter.dataset.filter;render();return;}const at=e.target.closest('[data-admin-tab]');if(at){adminTab=at.dataset.adminTab;render();return;}const mt=e.target.closest('[data-marketing-tab]');if(mt){marketingTab=mt.dataset.marketingTab;render();return;}const cat=e.target.closest('[data-category]');if(cat){const f=$('#risk-form');if(f)Object.assign(Q,Object.fromEntries(new FormData(f)));Q.category=cat.dataset.category;selectedOffer=null;render();return;}const prompt=e.target.closest('[data-prompt]');if(prompt){sendChat(prompt.dataset.prompt);return;}const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){
case 'close-modal':closeModal();break;
case 'menu':$('.shell')?.classList.toggle('menu-open');break;
case 'entry':closeModal();navigate('inicio');break;
case 'logout':role=null;sessionStorage.removeItem('turi.demo.role');navigate('inicio');toast('Sesión de demo cerrada.');break;
case 'login':modal(el.dataset.role==='cliente'?'Tu espacio de cliente':'Tu escritorio de productor',`<p>Acceso de demostración. No ingreses credenciales reales.</p><form id="login-form" class="login-form mt24" data-role="${el.dataset.role}"><label class="field">Usuario<input name="user" autocomplete="off" placeholder="Dani" required></label><label class="field">Contraseña<input name="password" type="password" autocomplete="off" placeholder="1234" required></label><div id="login-error" class="error" role="alert"></div><button class="btn blue" type="submit">Ingresar ${icon('arrow')}</button></form><p class="no-claims">Usuario <b>Dani</b> · contraseña <b>1234</b></p>`);break;
case 'demo-info':modal('Una demo para pensar la operación',`<p>TURI Gestión reúne la jornada del productor: cartera, siniestros, alertas, administración, ventas y asistencia contextual.</p><h3>Qué podés probar</h3><p>Resolver o posponer alertas, buscar 230 pólizas ficticias, registrar avances, crear una solicitud, descargar su PDF ilustrativo y aprobar un borrador de muestra.</p><h3>Qué está simulado</h3><p>Acceso Dani/1234, avisos de compañías, primas, comisiones, aprobación y agente. No hay APIs aseguradoras, LLM, pagos, emisión, correo ni WhatsApp conectados. Los botones a compañías son enlaces externos.</p><p class="mt16">Los cambios se guardan sólo en este navegador. No cargues información real. El enlace de esta demo es de acceso abierto y no requiere cuenta de ChatGPT.</p>`,button('Entendido','close-modal','blue'));break;
case 'alert-filters':modal('Alertas pensadas para tu jornada',`<p><b>Rojo</b>: acción para hoy o vencida.<br><b>Amarillo</b>: próxima fecha o seguimiento.<br><b>Verde</b>: novedad informativa.</p><h3>Filtros que vas a usar</h3><p>En la bandeja podés filtrar renovaciones, pagos y siniestros. “Más” reúne actualizaciones, bajas y recotizaciones. La configuración por compañía, frecuencia y cliente se validará con la rutina de Daniel en el piloto.</p><p class="mt16">Esta demo usa 19 de octubre como jornada fija para que los ejemplos no pierdan sentido con el paso de los días.</p>`,button('Volver a mi día','close-modal','blue'));break;
case 'alert-detail':{const a=S.alerts.find(a=>a.id===id);if(a?.draftId)draftDetail(a.draftId);else alertDetail(id);break;}
case 'alert-done':completeAlert(id);break;
case 'alert-snooze':{const a=S.alerts.find(a=>a.id===id);if(a){a.due=plusDays(a.due,1);if(a.priority==='red'&&a.due>S.demoDate)a.priority='yellow';audit('Alerta pospuesta 1 día',a.policyId);closeModal();render();toast('Nueva fecha de seguimiento registrada.')}break;}
case 'alert-message':{const a=S.alerts.find(a=>a.id===id);if(a)prepareMessage(a.policyId);break;}
case 'policy-detail':policyDetail(id);break;
case 'client-policy':policyDetail(id,true);break;
case 'policy-message':prepareMessage(id);break;
case 'copy-message':copy($('#message-draft').value);break;
case 'claim-detail':claimDetail(id);break;
case 'policy-prev':policyPage=Math.max(1,policyPage-1);render();break;
case 'policy-next':policyPage++;render();break;
case 'clear-policy-filters':policySearch='';policyCompany='';policyCategory='';policyPage=1;render();break;
case 'client-detail':{const c=S.clients.find(c=>c.id===id);const p=S.policies.find(p=>p.clientId===id);if(c)modal('Ficha de cliente',`<h3>${esc(c.name)}</h3><p>${esc(c.email)}<br>${esc(c.phone)}</p><div class="mt16">${badge(c.marketing?'Permiso de muestra para novedades':'Sin permiso de marketing',c.marketing?'green':'')}</div><h3>Póliza vinculada</h3><p>${esc(p?.category)} · ${esc(p?.id)}<br>${esc(p?.risk)}</p>`,`${button('Cerrar','close-modal','light')}${p?button('Ver póliza','policy-detail','blue',`data-id="${p.id}"`):''}`);break;}
case 'task-toggle':{const t=S.tasks.find(t=>t.id===id);if(t){t.done=!t.done;audit(t.done?'Control marcado revisado':'Control reabierto',id);render()}break;}
case 'registry-model':modal('Registro de muestra',`<p>La exportación de cartera contiene identificadores, cliente, riesgo, compañía y vencimiento para diseñar el próximo registro operativo.</p><p class="mt16">No constituye un libro rubricado ni una presentación ante la SSN. El formato real se validará antes de automatizar registros.</p>`,`${button('Cerrar','close-modal','light')}${button('Exportar cartera de muestra','export-policies','blue')}`);break;
case 'lead-detail':leadDetail(id);break;
case 'agent-day':closeModal();sendChat('Prepará mi día');break;
case 'open-agent':navigate('agente');break;
case 'providers':modal('Tu IA, con el contexto de Turi',providersView(),button('Cerrar','close-modal','light'));break;
case 'provider-detail':providerDetail(id);break;
case 'provider-select':S.preferences.provider=id;audit('Proveedor IA preferido elegido · sin conectar',id);closeModal();render();toast('Preferencia guardada. No hay una conexión activa.');break;
case 'upload-doc':pickFile('.txt,.pdf,.png,.jpg,.jpeg',recordDocument);break;
case 'doc-detail':{const d=S.documents.find(d=>d.id===id);if(d)modal(d.name,`<p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(d.text)}</p>`,button('Cerrar','close-modal','light'));break;}
case 'export-context':download('Turi-contexto-de-muestra.txt',`CONTEXTO FICTICIO PARA PROBAR UN AGENTE\nProductor: Daniel Stern · Turi\nSólo datos de muestra, sin credenciales.\n\n${S.documents.filter(d=>d.text).map(d=>d.name+'\n'+d.text).join('\n\n')}\n\nALERTAS\n${S.alerts.filter(a=>!a.done).map(a=>a.client+': '+a.title+' · '+a.due).join('\n')}\n\nSINIESTROS\n${S.claims.map(c=>c.id+' · '+c.client+' · '+daysSince(c.lastUpdate)+' días sin avance · '+c.next).join('\n')}\n\nNo emitir cobertura ni enviar mensajes. Proponer acciones y citar el registro utilizado.`);toast('Contexto de muestra exportado.');break;
case 'course-toggle':{const a=S.preferences.courses;a.includes(id)?a.splice(a.indexOf(id),1):a.push(id);save();render();break;}
case 'consulting':modal('Consultoría para agencias y brokers',`<h3>Cómo potenciar el día a día con un Agente Turi</h3><p>Relevamos la rutina, las compañías y los documentos. Elegimos un proceso acotado y probamos cuánto trabajo repetido se puede reducir.</p><h3>Un programa por etapas</h3><p>1. Mapa de procesos y prioridades.<br>2. Contexto, permisos y conexión de IA.<br>3. Un agente con herramientas verificables.<br>4. Capacitación del equipo y medición operativa.</p><p class="mt16">Contenido de propuesta para revisar con Turi. Los cursos, alcance y modalidad comercial aún no están contratados ni publicados.</p>`,button('Volver','close-modal','blue'));break;
case 'connection-detail':{const c=company(id);modal('Acceso · '+c.name,`<p>Código PAS de muestra: <b>${esc(c.code)}</b></p><h3>Siempre a nombre del productor</h3><p>Una futura conexión debe validar que el código y la cuenta pertenecen al PAS, respetar los permisos de la compañía y conservar atribución e historial. Las credenciales no se comparten entre productores.</p><div class="inline-hint mt24">Hoy este botón sólo abre el acceso oficial. No se guardan contraseñas de aseguradoras ni se simula un inicio de sesión ya realizado.</div>`,`${button('Cerrar','close-modal','light')}<a class="btn blue" href="${esc(c.portal)}" target="_blank" rel="noopener noreferrer">Abrir sitio oficial ${icon('external')}</a>`);break;}
case 'share-link':shareLink();break;
case 'copy-link':copy(quoteUrl());break;
case 'copy-share':copy($('#share-url').value);break;
case 'quote-category':closeModal();quoteStep=1;Q.category=insuranceFAQs[id]?id:'Autos';selectedOffer=null;navigate('cotizar/daniel-stern?ramo='+encodeURIComponent(Q.category));break;
case 'test-quote':closeModal();quoteStep=1;Q={category:'Autos',brand:'',model:'',year:'',postal:'',usage:'Particular',name:'',email:'',phone:'',marketing:false};selectedOffer=null;navigate('cotizar/daniel-stern');break;
case 'back-office':closeModal();if(role==='productor')navigate('cotizaciones');else navigate('inicio');break;
case 'quote-back':captureQuoteFields();quoteStep=Math.max(1,quoteStep-1);render();window.scrollTo(0,0);break;
case 'select-offer':selectedOffer=offers().find(o=>o.id===id);quoteStep=3;render();window.scrollTo(0,0);break;
case 'manual-continue':selectedOffer=null;quoteStep=3;render();window.scrollTo(0,0);break;
case 'human-help':humanHelp();break;
case 'draft-detail':draftDetail(id);break;
case 'download-draft':{const d=S.drafts.find(d=>d.id===id);if(d)download('Turi-'+id+'-PENDIENTE.pdf',makePDF('Solicitud de muestra '+id,[`Productor responsable: Daniel Stern / Turi`,`Solicitante: ${d.name}`,`Contacto: ${d.email}`,`Seguro: ${d.category}`,`Riesgo: ${d.brand||''} ${d.model||d.description||''} ${d.year||''} / CP ${d.postal}`,`Referencia: ${d.offer?.title||'Evaluacion experta pendiente'}`,`Prima: ${d.offer?money(d.offer.price)+' ficticios por mes':'Sin tarifa disponible'}`,`Estado: ${d.status==='pending'?'Pendiente de aprobacion del PAS':'Aprobacion simulada; sin cobertura emitida'}`,`Datos, requisitos y pago pendientes de validacion real.`,`Un asesor te contactara en las proximas 48 hs para avanzar.`,`El plazo corresponde al contacto y no garantiza emision.`,`Documento ilustrativo. No se consultaron tarifas de aseguradoras.`]),'application/pdf');break;}
case 'download-policy':{const p=S.policies.find(p=>p.id===id);if(p)download('Turi-'+id+'-MODELO.pdf',makePDF('Resumen de cartera ficticia',[`Referencia: ${id}`,`Cliente de muestra: ${p.client}`,`Seguro: ${p.category}`,`Bien: ${p.risk}`,`Compania: ${company(p.company).name}`,`Este registro no proviene de una poliza real.`,`Importes y estados son ficticios.`]),'application/pdf');break;}
case 'export-policies':download('Turi-cartera-ficticia.csv',csv([['Póliza','Cliente','Seguro','Bien','Compañía','Vencimiento','Estado','Prima ARS ficticia'],...S.policies.map(p=>[p.id,p.client,p.category,p.risk,company(p.company).name,p.expiry,p.status,p.premium])]),'text/csv;charset=utf-8');break;
case 'export-clients':download('Turi-clientes-ficticios.csv',csv([['ID','Nombre','Email de muestra','Marketing de muestra'],...S.clients.map(c=>[c.id,c.name,c.email,c.marketing?'Sí':'No'])]),'text/csv;charset=utf-8');break;
case 'export-claims':download('Turi-seguimiento-ficticio.csv',csv([['Caso','Cliente','Compañía','Estado','Último avance','Próximo paso'],...S.claims.map(c=>[c.id,c.client,company(c.company).name,c.stage,c.lastUpdate,c.next])]),'text/csv;charset=utf-8');break;
case 'export-admin':download('Turi-administracion-muestra.json',JSON.stringify({notice:'Datos ficticios. No es una declaración ni presentación fiscal.',tasks:S.tasks,period:'2026-10'},null,2),'application/json');break;
case 'backup':download('Turi-respaldo-demo.json',JSON.stringify(S,null,2),'application/json');toast('Copia de los datos de muestra descargada.');break;
case 'restore':pickFile('.json',async f=>{if(f.size>5*1024*1024){toast('La copia excede el tamaño máximo.');return;}try{const d=JSON.parse(await f.text());if(!validState(d))throw new Error();d.companies=clone(window.TURI_SEED.companies);S=d;save();render();toast('Copia de demo restaurada.')}catch{toast('El archivo no es una copia válida de esta demo.')}});break;
case 'reset':modal('Reiniciar esta demo',`<p>Se restaurarán las 230 pólizas ficticias y se eliminarán los cambios locales, documentos adjuntados y solicitudes de prueba.</p><p class="mt16">Podés exportar una copia antes de reiniciar.</p>`,`${button('Cancelar','close-modal','light')}${button('Exportar copia','backup','light')}${button('Reiniciar datos de muestra','reset-confirm','danger')}`);break;
case 'reset-confirm':S=clone(window.TURI_SEED);save();closeModal();render();toast('Datos de muestra restaurados.');break;
}});
document.addEventListener('change',e=>{if(e.target.id==='policy-company'){policyCompany=e.target.value;policyPage=1;render()}if(e.target.id==='policy-category'){policyCategory=e.target.value;policyPage=1;render()}if(e.target.id==='share-category')$('#share-url').value=quoteUrl(e.target.value)});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='policy-search'){policySearch=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;policyPage=1;render();$('#policy-search')?.focus();try{$('#policy-search').setSelectionRange(pos,pos)}catch{}},250)}if(e.target.id==='client-search')$('#clients-list').innerHTML=clientRows(e.target.value)});
document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('form'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));switch(f.id){case 'login-form':if(d.user.trim().toLowerCase()==='dani'&&d.password==='1234'){role=f.dataset.role;sessionStorage.setItem('turi.demo.role',role);closeModal();navigate(role==='productor'?'tablero':'cliente')}else $('#login-error').textContent='Usá Dani y 1234 para entrar a la demo.';break;
case 'global-search':policySearch=d.q.trim();policyPage=1;navigate('polizas');break;
case 'claim-form':if(registerClaim(f.dataset.id,{stage:d.stage,note:d.note,next:d.next})){closeModal();render();toast('Avance registrado. Se actualizó el seguimiento.')}break;
case 'risk-form':Object.assign(Q,d);selectedOffer=null;quoteStep=2;render();window.scrollTo(0,0);break;
case 'contact-form':{Object.assign(Q,d,{marketing:!!f.elements.marketing.checked});const attachments=[...f.elements.quoteDocs.files].slice(0,5).map(x=>x.name.slice(0,180));if(!Q.submissionId)Q.submissionId='DEMO-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);const draft=recordDraft({...Q,attachments,intent:!!f.elements.intent.checked,submissionId:Q.submissionId});if(draft){Q.draftId=draft.id;quoteStep=4;render();window.scrollTo(0,0)}break;}
case 'approve-form':{const checks=Object.fromEntries(['identityVerified','conditionsVerified','docsVerified','paymentVerified'].map(k=>[k,!!f.elements[k].checked]));if(approveDraft(f.dataset.id,checks)){closeModal();render();toast('Aprobación simulada registrada. No se emitió cobertura.')}else toast('Revisá los requisitos y el estado del borrador.');break;}
case 'chat-form':sendChat(d.message);break;
case 'lead-form':{const l=S.leads.find(l=>l.id===f.dataset.id);if(l){l.stage=d.stage;l.note=d.note;audit('Seguimiento comercial actualizado',l.id);closeModal();render();toast('Seguimiento guardado.')}break;}
case 'human-form':{Q.name=d.name;Q.email=d.email;S.leads.unshift({id:'H-'+Date.now(),name:d.name,category:Q.category,source:'Pedido de atención humana',stage:'Nueva consulta',marketing:false,note:d.need,email:d.email});S.alerts.unshift({id:'H-A-'+Date.now(),title:'Solicitud de atención experta',category:'Actualizaciones',priority:'yellow',company:'',client:d.name,due:plusDays(S.demoDate,1),source:'Formulario del productor · demo',detail:d.need,done:false});audit('Atención humana solicitada · muestra',d.name);modal('Tu consulta quedó preparada',`<p>Daniel podrá ver tu necesidad en las oportunidades de la demo.</p><p class="mt16">Guardamos los datos cargados en este navegador. No enviamos un correo ni notificamos a una persona real.</p>`,button('Seguir','close-modal','blue'));break;}
case 'campaign-form':messageModal(`Tu ${d.topic.toLowerCase()}, con la atención que necesita.\n\nEn Turi te ayudamos a entender qué estás asegurando y a evaluar alternativas con criterio profesional. Empezá con pocos datos y contá con un experto cuando lo necesites.\n\nCotizá acá: ${quoteUrl(d.topic)}\n\nHacelo simple, hacelo Turi.\n\nBorrador para ${d.channel}. Revisar alcance, marca y condiciones antes de publicar.`,'Borrador de contenido');break;
}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
render();
